Lemma sl_chunk_stk : forall (m : mem), wmono asegs m2 m -> stk asegs m P (P + msz).
Proof using SKM. clear - SKM. intros m WM. exact (stk_wmono m2 m _ _ SKM WM). Qed.
Lemma sl_shadow_stk : forall (m : mem), wmono asegs m2 m -> stk asegs m (shad P) (shad (P + msz)).
Proof using SST. clear - SST. intros m WM. exact (stk_wmono m2 m _ _ SST WM). Qed.

